const looksLikeImage = (file, head) => /^image\//.test(file.type || '') || (head.length >= 12 && String.fromCharCode(head[0], head[1], head[2], head[3]) === 'RIFF' && String.fromCharCode(head[8], head[9], head[10], head[11]) === 'WEBP') || (head.length >= 8 && head[0] === 0x89 && head[1] === 0x50 && head[2] === 0x4E && head[3] === 0x47) || (head.length >= 3 && head[0] === 0xFF && head[1] === 0xD8 && head[2] === 0xFF);
function fileToSquareAvatar(file){
  return new Promise((resolve,reject)=>{
    if(!file)return reject(new Error('No file selected.'));
    if(file.size>8*1024*1024)return reject(new Error('That picture is too large. Please use one under 8MB.'));
    const probe = file.size >= 16 ? file.slice(0, 16).arrayBuffer().then(b => new Uint8Array(b)).catch(() => new Uint8Array(0)) : Promise.resolve(new Uint8Array(0));
    probe.then(head => {
      if(!looksLikeImage(file, head))return reject(new Error('Only JPG, PNG and WebP pictures are supported.'));
      const url=URL.createObjectURL(file);
      const img=new Image();
      img.onload=()=>{ URL.revokeObjectURL(url);
        const S=256, canvas=document.createElement('canvas'); canvas.width=S; canvas.height=S;
        const ctx=canvas.getContext('2d');
        const min=Math.min(img.width,img.height);
        const sx=(img.width-min)/2, sy=(img.height-min)/2;
        ctx.imageSmoothingEnabled=true; ctx.imageSmoothingQuality='high';
        ctx.drawImage(img,sx,sy,min,min,0,0,S,S);
        canvas.toBlob(blob=>{ if(blob)resolve(blob); else reject(new Error('Could not process that picture.')); },'image/webp',0.86);
      };
      img.onerror=()=>{ URL.revokeObjectURL(url); reject(new Error('Could not read that picture.')); };
      img.src=url;
    });
  });
}
