function bindApp(){ try{keepPinnedOnMediaLoad();}catch(e){} $('#message-form').onsubmit=e=>{e.preventDefault();submitMessage()}; $('#message-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&prefs().enterToSend){e.preventDefault();submitMessage();}}; document.addEventListener('keydown',e=>{const t=e.target;if(!t||t.tagName!=='TEXTAREA'||t.id==='message-input'||t.id==='edit-input')return;if(e.key==='Enter'&&!e.shiftKey&&(prefs().enterToSend||t.id==='edit-input')){const form=t.closest('form');if(form){e.preventDefault();form.requestSubmit?form.requestSubmit():form.submit();}}}); document.addEventListener('keydown',e=>{const k=e.key;if(k!=='Escape'&&k!=='Esc')return;const mr=$('#modal-root');if(mr&&mr.innerHTML.trim()){closeModal();return;}if(pendingImages.length){const n=pendingImages.length;clearPendingImages();toast(`Cleared ${n} ${n===1?'attachment':'attachments'}`);return;}if(replyTarget){clearReply();}});
$('#message-input').oninput=e=>{const r=$('#messages');const near=r.scrollTop+r.clientHeight>=r.scrollHeight-48;e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,140)+'px';if(near)r.scrollTop=r.scrollHeight;if(active&&prefs().sendTyping){clearTimeout(typingTimer);if(e.target.value.trim()){socket?.emit('typing',{conversationId:active.id,isTyping:true});typingTimer=setTimeout(()=>socket?.emit('typing',{conversationId:active.id,isTyping:false}),300);}else{socket?.emit('typing',{conversationId:active.id,isTyping:false});}}}; const eb=$('#emoji');if(eb)eb.onclick=()=>{ if(window.NCEmoji) return window.NCEmoji.toggle(); $('#message-input').value+='😊';$('#message-input').focus(); }; $('#attach').onclick=()=>$('#image-input').click(); $('#image-input').onchange=e=>{if(!active)return;const files=Array.from(e.target.files||[]);e.target.value='';if(!files.length)return;let added=0,tooBig=0,bad=0;for(const f of files){const t=f.type||'';let kind=null;if(/^image\/(png|jpeg|jpg|gif|webp)$/.test(t))kind='image';else if(/^video\/(mp4|webm|quicktime|ogg|x-m4v|x-matroska)$/.test(t))kind='video';if(!kind){bad++;continue;}if(f.size>UPLOAD_LIMIT){tooBig++;continue;}pendingImages.push({url:URL.createObjectURL(f),file:f,name:f.name||'upload',kind});added++;}if(added){renderPastePreview();toast(added>1?`${added} files added — click Send`:'Ready to send — click Send');}if(tooBig)toast(`Skipped ${tooBig} file${tooBig>1?'s':''} over ${uploadLimitLabel()}.`,'error');if(bad)toast('Unsupported file type. Use JPG, PNG, GIF, WebP, MP4, WebM or MOV.','error');}; $('#search').oninput=e=>{clearTimeout(searchTimer);const q=e.target.value.toLowerCase();renderConversations(conversations.filter(c=>c.other.username.toLowerCase().includes(q)||c.other.id.toLowerCase().includes(q)));}; $('#add-member').onclick=showAdd; $('#welcome-add').onclick=showAdd; $('#open-sidebar').onclick=()=>$('#sidebar').classList.add('open'); $('#close-sidebar').onclick=()=>$('#sidebar').classList.remove('open'); $('#profile-trigger').onclick=showProfile; $('#settings-trigger').onclick=()=>{if(window.NCSettings)window.NCSettings.open();}; $('#chat-settings').onclick=showChatSettings; $('#person-profile').onclick=()=>{ if(!active)return; if(isOversight())showOversightMembers(); else showPublicProfile(active.other); }; const atAdmin=$('#admin-trigger'); if(atAdmin)atAdmin.onclick=()=>{ if(window.openAdminDashboard) openAdminDashboard(); else toast('Loading admin…'); }; $('#logout').onclick=async()=>{await api('/api/logout',{method:'POST'});location.reload()}; $('#theme-toggle').onclick=()=>{const a=getLocalAppearance();a.mode=document.body.classList.contains('light')?'dark':'light';applyAppearance(a);persistLocalAppearance(a);saveAppearanceToServer(a)} }
function modal(title,body){$('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"> <div class="modal-head"><h3>${title}</h3><button class="close" onclick="closeModal()">×</button></div>${body}</div></div>`}function closeModal(){$('#modal-root').innerHTML=''}window.onpopstate=()=>{if(/^\/settings\/?$/.test(location.pathname)){if(window.NCSettings&&typeof me!=='undefined'&&me){window.NCSettings.open();return;}}if(window.NCSettings&&window.NCSettings.isOpen()){window.NCSettings.close(true);return;}const who=(location.pathname.match(/^\/([^\/]+)\/message$/i)||[])[1];const c=who&&conversations.find(x=>x.other.username.toLowerCase()===decodeURIComponent(who).toLowerCase());if(c)openConversation(c.id);else showWelcome();};
function showAdd(){modal('Add a member',`<p class="muted">Enter their username to start a private conversation.</p><form id="member-form"><label>Username<input name="memberId" placeholder="e.g. sara" autocomplete="off" required></label><div class="modal-actions"><button type="button" class="secondary" onclick="closeModal()">Cancel</button><button class="primary" type="submit">Find member</button></div></form><div id="member-result"></div>`);$('#member-form').onsubmit=async e=>{e.preventDefault();const q=String(new FormData(e.target).get('memberId')).trim();if(!q)return;try{const d=await api('/api/users?q='+encodeURIComponent(q));if(!d.users.length)return $('#member-result').innerHTML=`<p style="color:var(--danger);font-size:12px">No user found.</p>`;const rows=d.users.slice(0,3).map(u=>`<div class="member-result">${avatar(u)}<div class="meta"><strong>${escapeHTML(u.name||u.username)}${roleBadge(u)}</strong><small>@${escapeHTML(u.username)} · ${escapeHTML(u.bio)}</small></div><button class="primary" data-uid="${u.id}">Message</button></div>`).join('');$('#member-result').innerHTML=rows;$$('#member-result [data-uid]').forEach(b=>b.onclick=async()=>{try{const c=await api('/api/conversations',{method:'POST',body:JSON.stringify({memberId:b.dataset.uid})});closeModal();await loadConversations();openConversation(c.conversation.id)}catch(err){toast(err.message,'error')}})}catch(err){$('#member-result').innerHTML=`<p style="color:var(--danger);font-size:12px">${escapeHTML(err.message)}</p>`}}}
function showProfile(){modal('Your profile',`<div style="display:flex;gap:14px;align-items:center;margin-bottom:16px"><div id="profile-avatar-cell" style="position:relative">${avatar(me,'small')}</div><div style="min-width:0"><strong style="font-size:17px">${escapeHTML(me.name||me.username)}</strong><p class="muted" style="margin:4px 0 0">@${escapeHTML(me.username)}</p><div style="display:flex;gap:8px;margin-top:10px"><button type="button" class="secondary" id="avatar-change">📷 &nbsp;Change photo</button>${me.avatar?'<button type="button" class="secondary" id="avatar-remove">✕ &nbsp;Remove</button>':''}<input type="file" id="avatar-file" accept="image/jpeg,image/png,image/webp,.jpg,.jpeg,.png,.webp" class="hidden"></div></div></div><form id="profile-form"><label>Name<input name="name" value="${escapeHTML(me.name||me.username)}"></label><label>Username<input name="username" value="${escapeHTML(me.username)}"></label><label>Bio<textarea name="bio" rows="3">${escapeHTML(me.bio)}</textarea></label><label>Accent color<input name="color" type="color" value="${me.color}"></label><div class="modal-actions"><button type="button" class="secondary" onclick="closeModal()">Cancel</button><button class="primary">Save profile</button></div></form>`);$('#profile-form').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/profile',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});me=d.user;renderMe();closeModal();toast('Profile updated')}catch(err){toast(err.message,'error')}};$('#avatar-change').onclick=()=>$('#avatar-file').click();const rm=$('#avatar-remove');if(rm)rm.onclick=async()=>{rm.disabled=true;try{await api('/api/avatar/remove',{method:'POST',body:'{}'});applyAvatarChange(me.id,'');$('#profile-avatar-cell').innerHTML=avatar(me,'small');rm.remove();toast('Profile picture removed')}catch(err){toast(err.message,'error')}rm.disabled=false};$('#avatar-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{const blob=await fileToSquareAvatar(file);await setOwnAvatarBlob(blob,file.name);$('#profile-avatar-cell').innerHTML=avatar({...me},'small');toast('Profile picture updated')}catch(err){toast(err.message,'error')}}}
function showPublicProfile(u){modal(escapeHTML(u.name||u.username),`<div style="display:grid;place-items:center;text-align:center;gap:10px">${avatar(u,'small')}<h3 style="margin:5px 0 0">${escapeHTML(u.name||u.username)}${roleBadge(u)}</h3><span style="color:var(--muted);font-size:12px">@${escapeHTML(u.username)}</span><span style="color:${u.online?'var(--green)':'var(--danger)'};font-size:12px">${u.online?'● Online':'○ Offline'}</span><p class="muted" style="margin:3px 0">${escapeHTML(u.bio)}</p><button class="primary" onclick="closeModal()">Close</button></div>`)}
function showSettings(){modal('Settings',`<div style="display:grid;gap:8px"><button class="nav-btn" onclick="closeModal();showProfile()">✎ &nbsp; Edit profile</button><button class="nav-btn" onclick="closeModal();showAppearance()">🎨 &nbsp; Theme & appearance</button><button class="nav-btn danger" onclick="closeModal();$('#logout').click()">↪ &nbsp; Log out</button></div>`)}
function showAppearance(){const cur=getLocalAppearance();savedAppearance=me&&me.appearance?{...me.appearance}:savedAppearance;let pending={...savedAppearance};
  const swatch=(id,arr)=>`<button class="theme-swatch${pending.theme===id?' active':''}" data-theme="${id}" title="${APPEARANCE_THEMES[id]}"><i style="background:${arr[0]}"></i><i style="background:${arr[1]}"></i><span>${APPEARANCE_THEMES[id]}</span></button>`;
  const gswatch=(id)=>`<button class="grad-swatch${pending.gradient===id?' active':''}" data-gradient="${id}" title="${APPEARANCE_GRADIENTS[id]}"><i style="${GRAD_SWATCH[id]||'background:var(--card2)'}"></i><span>${APPEARANCE_GRADIENTS[id]}</span></button>`;
  const render=()=>{modal('Theme & appearance',`<p class="muted" style="margin:0 0 12px">These options preview instantly across the whole interface. Press Save to keep them or Cancel to discard.</p>
  <label>Mode</label><div id="appearance-mode" class="appearance-seg"><button class="${pending.mode==='dark'?'active':''}" data-mode="dark">🌙 &nbsp;Dark</button><button class="${pending.mode==='light'?'active':''}" data-mode="light">☀️ &nbsp;Light</button></div>
  <label>Color theme</label><div class="appearance-grid">${Object.keys(APPEARANCE_THEMES).map(k=>swatch(k,THEME_SWATCH[k])).join('')}</div>
  <label>Background</label><div class="appearance-grid">${Object.keys(APPEARANCE_GRADIENTS).map(gswatch).join('')}</div>
  <p class="muted" style="font-size:11px">Saved to your account and restored automatically after login.</p>
  <div class="modal-actions"><button type="button" class="secondary" onclick="closeModal()">Cancel</button><button class="primary" id="appearance-save">Save appearance</button></div>`);
  $$('.theme-swatch').forEach(b=>b.onclick=()=>{pending.theme=b.dataset.theme;applyAppearance(pending);render()});
  $$('.grad-swatch').forEach(b=>b.onclick=()=>{pending.gradient=b.dataset.gradient;applyAppearance(pending);render()});
  $$('#appearance-mode [data-mode]').forEach(b=>b.onclick=()=>{pending.mode=b.dataset.mode;applyAppearance(pending);render()});
  $('#appearance-save').onclick=async()=>{try{const d=await api('/api/appearance',{method:'PUT',body:JSON.stringify(pending)});savedAppearance={...d.appearance};if(me)me.appearance={...d.appearance};persistLocalAppearance(d.appearance);applyAppearance(d.appearance);closeModal();toast('Appearance saved')}catch(err){toast(err.message,'error')}};
};render()}
function showChatSettings(){if(!active)return;if(isOversight())return toast('Not available in owner mode.','error');modal('Conversation settings',`<p class="muted">Share this conversation</p><button class="secondary" style="margin-top:6px" onclick="navigator.clipboard.writeText(location.origin+'/'+encodeURIComponent(active.other.username)+'/message').then(()=>{closeModal();toast('Chat link copied')}).catch(()=>toast('Could not copy link','error'))">🔗 Copy chat link</button>`)}
function showWelcome(){ oversight=null; active=null; clearPendingImages(); $('#typing').classList.add('hidden'); $('#messages').innerHTML='<div class="welcome-state"><div class="welcome-icon">✦</div><h2>Your conversations, your way.</h2><p>Add a member from the sidebar to begin a private conversation.</p><button class="primary" id="welcome-add">＋ Add a member</button></div>'; $('#welcome-add').onclick=showAdd; $('#chat-person').innerHTML='<div class="avatar small">N</div><div><h2>Select a conversation</h2><p>Choose a person to start chatting</p></div>'; $('#message-input').disabled=true; const sb=$('.send-btn'); if(sb)sb.disabled=true; }
function syncKeyboard(){try{const vv=window.visualViewport;let kb=0;if(vv&&typeof window.innerHeight==='number')kb=Math.max(0,window.innerHeight-vv.height-(vv.offsetTop||0));document.documentElement.style.setProperty('--kb',kb+'px');}catch(e){}}
function msgMenuOutside(e){const el=$('#msg-menu');if(el&&e&&e.target&&!el.contains(e.target))closeMsgMenu();}
function sidebarOutside(e){const sb=$('#sidebar');if(sb&&sb.classList.contains('open')&&e&&e.target&&!sb.contains(e.target)&&!(e.target.closest&&e.target.closest('#open-sidebar')))sb.classList.remove('open');}
function initMobileChrome(){if(initMobileChrome.done)return;initMobileChrome.done=true;try{if(window.visualViewport){window.visualViewport.addEventListener('resize',syncKeyboard);window.visualViewport.addEventListener('scroll',syncKeyboard);}}catch(e){}window.addEventListener('resize',syncKeyboard);document.addEventListener('pointerdown',msgMenuOutside);document.addEventListener('pointerdown',sidebarOutside);syncKeyboard();const mi=$('#message-input');if(mi)mi.addEventListener('focus',()=>{try{const r=$('#messages');if(r)r.scrollTop=r.scrollHeight;}catch(e){}});}
function bootApp(){ show('app'); try{initMobileChrome();}catch(e){} renderMe(); if(me.appearance){savedAppearance={...me.appearance};applyAppearance(me.appearance);persistLocalAppearance(me.appearance)}else applyAppearance(getLocalAppearance()); if(me.owner){const at=$('#admin-trigger'); if(at)at.classList.remove('hidden');} bindApp(); connectSocket(); try{if(socket&&socket.setPresenceEnabled)socket.setPresenceEnabled(!prefs().invisible);}catch(e){} try{if(window.NCCall&&window.NCCall.init)window.NCCall.init();}catch(e){} loadConversations().then(()=>{ if(/^\/settings\/?$/.test(location.pathname)&&window.NCSettings){window.NCSettings.open();return;} const who=(location.pathname.match(/^\/([^\/]+)\/message$/i)||[])[1]; if(who){ const c=conversations.find(x=>x.other.username.toLowerCase()===decodeURIComponent(who).toLowerCase()); if(c)openConversation(c.id); } }); }
(async function init(){bindAuth();initGoogleAuth();applyAppearance(getLocalAppearance());const p=new URLSearchParams(location.search);const isCb=/^\/auth\/callback$/.test(location.pathname)||(location.pathname==='/'&&p.has('code'));if(isCb){if(await handleAuthCallback())return;}setTimeout(async()=>{try{const d=await api('/api/me');if(d.user){me=d.user;bootApp()}else show('auth')}catch{show('auth')}},isCb?600:2000)})();
